import java.util.Arrays;
import java.util.Scanner;

public class Main {
    static final int INF = 1_000_000_000;

    static int[][] multiply(int[][] A, int[][] B) {
        int n = A.length;
        int[][] C = new int[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(C[i], INF);
        }
        for (int i = 0; i < n; i++) {
            for (int k = 0; k < n; k++) {
                if (A[i][k] == INF) continue;
                for (int j = 0; j < n; j++) {
                    if (B[k][j] == INF) continue;
                    int val = A[i][k] + B[k][j];
                    if (val < C[i][j]) C[i][j] = val;
                }
            }
        }
        return C;
    }

    static int[][] matPow(int[][] base, int exp) {
        int n = base.length;
        int[][] res = new int[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(res[i], INF);
            res[i][i] = 0;
        }
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = multiply(res, base);
            }
            base = multiply(base, base);
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int m = in.nextInt();
        int[] a = new int[n];
        int[] b = new int[n];
        for (int i = 0; i < n; i++) a[i] = in.nextInt();
        for (int i = 0; i < n; i++) b[i] = in.nextInt();
        in.close();

        int maxBal = n * 2;
        int[][] T = new int[maxBal + 1][maxBal + 1];
        for (int i = 0; i <= maxBal; i++) {
            Arrays.fill(T[i], INF);
        }

        for (int s = 0; s <= maxBal; s++) {
            int[][] dp = new int[n + 1][maxBal + 1];
            for (int i = 0; i <= n; i++) Arrays.fill(dp[i], INF);
            dp[0][s] = 0;
            for (int pos = 0; pos < n; pos++) {
                for (int bal = 0; bal <= maxBal; bal++) {
                    int cur = dp[pos][bal];
                    if (cur == INF) continue;
                    // open
                    if (bal + 1 <= maxBal) {
                        int nv = cur + a[pos];
                        if (nv < dp[pos + 1][bal + 1]) dp[pos + 1][bal + 1] = nv;
                    }
                    // close
                    if (bal > 0) {
                        int nv = cur + b[pos];
                        if (nv < dp[pos + 1][bal - 1]) dp[pos + 1][bal - 1] = nv;
                    }
                }
            }
            for (int e = 0; e <= maxBal; e++) {
                T[s][e] = dp[n][e];
            }
        }

        int[][] TM = matPow(T, m);
        System.out.println(TM[0][0]);
    }
}
